code='''def transform(grid):
    g=[row[:] for row in grid]
    bg=max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    motif=None
    for row in grid:
        runs=[]; cur=[]
        for v in row+[bg]:
            if v!=bg: cur.append(v)
            elif cur:
                runs.append(cur); cur=[]
        if runs and max(map(len,runs))>=3:
            motif=max(runs,key=len); break
    if motif is None: return g
    colors=set(motif)
    marker=min((v for v in set(v for row in grid for v in row) if v!=bg and v not in colors), key=lambda x: sum(row.count(x) for row in grid))
    for r,row in enumerate(grid):
        for c,v in enumerate(row):
            if v==marker:
                start=c-len(motif)//2
                for k,x in enumerate(motif):
                    if 0<=start+k<len(row): g[r][start+k]=x
    return g
'''
